		expect(screen.getByText("true")).toBeInTheDocument();
		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({
					structuredContent: {},
					_meta: {
						"lobu/mcp-app-snapshot-capability": "replayed-capability",
					},
				});
			}
		});
		expect(screen.getByText("Capability-restored result")).toBeInTheDocument();
		act(() => {
			window.dispatchEvent(
				new CustomEvent("openai:set_globals", {
					detail: {
						globals: { toolOutput: { structuredContent: {} } },
					},
				}),
			);
		});
		fireEvent.click(screen.getByRole("button", { name: "Collapse" }));
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "save_lobu_app_state",
				arguments: {
					tool_name: "query_sdk",
					view_state: { "payload.open": false },
					snapshot_capability: "replayed-capability",
				},
				_meta: {
					"lobu/mcp-app-snapshot-capability": "replayed-capability",
				},
			}),
		);
		);
		expect(
			bridge.callServerTool.mock.calls.filter(
				([request]) => request.name === "restore_lobu_app_result",
			),
		).toHaveLength(1);
	});

	it("does not let a delayed restore overwrite newer live output", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://chatgpt.com" },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		let resolveRestore!: (result: {
			isError: false;
			structuredContent: {
				found: true;
				tool_name: string;
				data: { title: string };
				view_state: Record<string, never>;
			};
		}) => void;
		const restore = new Promise<{
			isError: false;
			structuredContent: {
				found: true;
				tool_name: string;
				data: { title: string };
				view_state: Record<string, never>;
			};
		}>((resolve) => {
			resolveRestore = resolve;
		});
		bridge.callServerTool.mockImplementation(async ({ name }) => {
			if (name === "restore_lobu_app_result") return restore;
			return { isError: false };
		});

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data } = useMcpApp<{ title: string }>();
			return <span>{data?.title}</span>;
		}

		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({
					structuredContent: {},
					_meta: {
						"lobu/mcp-app-snapshot-capability": "stale-capability",
					},
				});
			}
		});
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "restore_lobu_app_result",
				arguments: { snapshot_capability: "stale-capability" },
			}),
		);

		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({
					structuredContent: { title: "Current live result" },
					_meta: {
						"lobu/mcp-app-snapshot-capability": "current-capability",
					},
				});
			}
		});
		expect(await screen.findByText("Current live result")).toBeInTheDocument();
		await act(async () => {
			resolveRestore({
				isError: false,
				structuredContent: {
					found: true,
					tool_name: "query_sdk",
					data: { title: "Stale restored result" },
					view_state: {},
				},
			});
			await restore;
		});

		expect(screen.getByText("Current live result")).toBeInTheDocument();
		expect(screen.queryByText("Stale restored result")).not.toBeInTheDocument();
	});

	it("does not apply a restore after the host card identity changes", async () => {
		type RestoreResult = {
			isError: false;
			structuredContent: {
				found: true;
				tool_name: string;
				data: { title: string };
				view_state: Record<string, never>;
			};
		};
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://chatgpt.com" },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		bridge.hostContext = {
			toolInfo: { id: "old-card", tool: { name: "query_sdk" } },
		};
		let resolveOldRestore!: (result: RestoreResult) => void;
		let resolveCurrentRestore!: (result: RestoreResult) => void;
		const oldRestore = new Promise<RestoreResult>((resolve) => {
			resolveOldRestore = resolve;
		});
		const currentRestore = new Promise<RestoreResult>((resolve) => {
			resolveCurrentRestore = resolve;
		});
		bridge.callServerTool.mockImplementation(
			async ({ name, arguments: args }) => {
				if (name !== "restore_lobu_app_result") return { isError: false };
				return args.tool_call_id === "old-card" ? oldRestore : currentRestore;
			},
		);

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data } = useMcpApp<{ title: string }>();
			return <span>{data?.title ?? "No result"}</span>;
		}

		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);
		await screen.findByText("No result");
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "restore_lobu_app_result",
				arguments: {
					tool_call_id: "old-card",
					tool_name: "query_sdk",
				},
			}),
		);

		bridge.hostContext = {
			toolInfo: { id: "current-card", tool: { name: "query_sdk" } },
		};
		act(() => {
			for (const handler of bridge.listeners.get("hostcontextchanged") ?? []) {
				handler({ theme: "light" });
			}
		});
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "restore_lobu_app_result",
				arguments: {
					tool_call_id: "current-card",
					tool_name: "query_sdk",
				},
			}),
		);

		await act(async () => {
			resolveOldRestore({
				isError: false,
				structuredContent: {
					found: true,
					tool_name: "query_sdk",
					data: { title: "Stale old card" },
					view_state: {},
				},
			});
			await oldRestore;
		});
		expect(screen.getByText("No result")).toBeInTheDocument();
		expect(screen.queryByText("Stale old card")).not.toBeInTheDocument();

		await act(async () => {
			resolveCurrentRestore({
				isError: false,
				structuredContent: {
					found: true,
					tool_name: "query_sdk",
					data: { title: "Current card result" },
					view_state: {},
				},
			});
			await currentRestore;
		});
		expect(await screen.findByText("Current card result")).toBeInTheDocument();
	});

	it("restores a missing result by the originating host tool-call id", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: window.location.origin },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		bridge.hostContext = {
			toolInfo: { id: "call-77", tool: { name: "query_sql" } },
		};
		bridge.callServerTool.mockImplementation(
			async ({ name, arguments: args }) => {
				if (name === "restore_lobu_app_result") {
					expect(args).toEqual({
						tool_call_id: "call-77",
						tool_name: "query_sql",
					});
					return {
						isError: false,
						structuredContent: {
							found: true,
							tool_name: "query_sql",
							data: { title: "Restored result" },
							view_state: { "table.sql.page": 1 },
						},
					};
				}
				return { isError: false };
			},
		);

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, setViewState, toolName, viewState } = useMcpApp<{
				title: string;
			}>();
			return (
				<>
					<span>{data?.title}</span>
					<span>{toolName}</span>
					<span>{String(viewState["table.sql.page"])}</span>
					<button
						type="button"
						onClick={() => setViewState("table.sql.page", 2)}
					>
						Next page
					</button>
				</>
			);
		}

		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);

		expect(await screen.findByText("Restored result")).toBeInTheDocument();
		expect(screen.getByText("query_sql")).toBeInTheDocument();
		expect(screen.getByText("1")).toBeInTheDocument();
		fireEvent.click(screen.getByRole("button", { name: "Next page" }));
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "save_lobu_app_state",
				arguments: {
					tool_call_id: "call-77",
					tool_name: "query_sql",
					view_state: { "table.sql.page": 2 },
				},
			}),
		);
	});
});

